To implement an idiomatic Rust LRU cache with these requirements, we use `std::collections::HashMap` for $O(1)$ lookups and a `std::collections::VecDeque` for tracking access order. For weak references, we use `std::sync::Weak` and `Arc`, which is the standard way to handle shared ownership and weak tracking in Rust.

To avoid `.clone()` on the hot path while maintaining the LRU order (which requires moving keys), we store the key in an `Arc<String>`.

### 1. Cargo.toml

```toml
[package]
name = "rust_lru_cache"
version = "0.1.0"
edition = "2021"

[dependencies]
tokio = { version = "1.0", features = ["full"] }
parking_lot = "0.12" # Better performance than std::sync::Mutex
```

### 2. src/lib.rs

```rust
use parking_lot::RwLock;
use std::collections::{HashMap, VecDeque};
use std::sync::{Arc, Weak};
use std::time::{Duration, Instant};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum EvictReason {
    Expired,
    Lru,
    Memory,
}

pub struct CacheEntry<V> {
    pub value: Arc<V>,
    pub expires_at: Instant,
    pub size: usize,
    pub last_accessed: Instant,
    pub access_count: usize,
}

pub struct CacheStats {
    pub hits: usize,
    pub misses: usize,
    pub evictions: usize,
    pub expirations: usize,
    pub size: usize,
    pub memory: usize,
}

pub struct CacheConfig {
    pub max_entries: usize,
    pub default_ttl: Duration,
    pub max_memory_bytes: usize,
    pub eviction_check_interval: Duration,
    pub on_evict: Option<Box<dyn Fn(String, EvictReason) + Send + Sync>>,
}

impl Default for CacheConfig {
    fn default() -> Self {
        Self {
            max_entries: 1000,
            default_ttl: Duration::from_secs(60),
            max_memory_bytes: 100 * 1024 * 1024,
            eviction_check_interval: Duration::from_secs(5),
            on_evict: None,
        }
    }
}

struct Inner<V> {
    entries: HashMap<Arc<String>, CacheEntry<V>>,
    access_order: VecDeque<Arc<String>>,
    weak_refs: HashMap<Arc<String>, Weak<V>>,
    current_memory: usize,
    stats: CacheStats,
    config: CacheConfig,
}

pub struct LRUCache<V> {
    inner: Arc<RwLock<Inner<V>>>,
}

impl<V: Send + Sync + 'static> LRUCache<V> {
    pub fn new(config: CacheConfig) -> Self {
        let stats = CacheStats {
            hits: 0,
            misses: 0,
            evictions: 0,
            expirations: 0,
            size: 0,
            memory: 0,
        };
        Self {
            inner: Arc::new(RwLock::new(Inner {
                entries: HashMap::new(),
                access_order: VecDeque::new(),
                weak_refs: HashMap::new(),
                current_memory: 0,
                stats,
                config,
            })),
        }
    }

    pub fn get(&self, key: &str) -> Option<Arc<V>> {
        let mut inner = self.inner.write();

        // Find key in entries
        let arc_key = inner.entries.keys().find(|k| k.as_str() == key)?.clone();

        let entry = inner.entries.get_mut(&arc_key)?;
        if Instant::now() > entry.expires_at {
            drop(entry);
            self.delete_inner(&mut inner, &arc_key, EvictReason::Expired);
            inner.stats.misses += 1;
            return None;
        }

        entry.last_accessed = Instant::now();
        entry.access_count += 1;

        // Move to front (LRU)
        inner.access_order.retain(|k| k.as_str() != key);
        inner.access_order.push_front(arc_key);

        inner.stats.hits += 1;
        Some(inner.entries.get(key).unwrap().value.clone())
    }

    pub fn put(&self, key: String, value: V, ttl: Option<Duration>, size: Option<usize>) {
        let mut inner = self.inner.write();
        let val_arc = Arc::new(value);
        let size = size.unwrap_or_else(|| std::mem::size_of::<V>());
        let ttl = ttl.unwrap_or(inner.config.default_ttl);
        let key_arc = Arc::new(key);

        // Remove existing
        if let Some(old) = inner.entries.remove(&key_arc) {
            inner.current_memory -= old.size;
            inner.access_order.retain(|k| k != &key_arc);
        }

        // Enforce memory limits
        while inner.current_memory + size > inner.config.max_memory_bytes && !inner.access_order.is_empty() {
            self.evict_lru(&mut inner, EvictReason::Memory);
        }

        // Enforce entry limits
        while inner.entries.len() >= inner.config.max_entries && !inner.access_order.is_empty() {
            self.evict_lru(&mut inner, EvictReason::Lru);
        }

        let entry = CacheEntry {
            value: val_arc.clone(),
            expires_at: Instant::now() + ttl,
            size,
            last_accessed: Instant::now(),
            access_count: 0,
        };

        inner.current_memory += size;
        inner.weak_refs.insert(key_arc.clone(), Arc::downgrade(&val_arc));
        inner.entries.insert(key_arc.clone(), entry);
        inner.access_order.push_front(key_arc);
    }

    fn evict_lru(&self, inner: &mut Inner<V>, reason: EvictReason) {
        if let Some(oldest_key) = inner.access_order.pop_back() {
            self.delete_inner(inner, &oldest_key, reason);
        }
    }

    fn delete_inner(&self, inner: &mut Inner<V>, key: &Arc<String>, reason: EvictReason) -> bool {
        if let Some(entry) = inner.entries.remove(key) {
            inner.current_memory -= entry.size;
            inner.access_order.retain(|k| k != key);
            inner.weak_refs.remove(key);

            match reason {
                EvictReason::Expired => inner.stats.expirations += 1,
                _ => inner.stats.evictions += 1,
            }

            if let Some(ref callback) = inner.config.on_evict {
                callback(key.to_string(), reason);
            }
            return true;
        }
        false
    }

    pub fn has(&self, key: &str) -> bool {
        let mut inner = self.inner.write();
        let arc_key = match inner.entries.keys().find(|k| k.as_str() == key) {
            Some(k) => k.clone(),
            None => return false,
        };

        if Instant::now() > inner.entries.get(&arc_key).unwrap().expires_at {
            self.delete_inner(&mut inner, &arc_key, EvictReason::Expired);
            return false;
        }
        true
    }

    pub fn get_stats(&self) -> CacheStats {
        let inner = self.inner.read();
        CacheStats {
            hits: inner.stats.hits,
            misses: inner.stats.misses,
            evictions: inner.stats.evictions,
            expirations: inner.stats.expirations,
            size: inner.entries.len(),
            memory: inner.current_memory,
        }
    }

    pub fn start_eviction_loop(&self) -> tokio::task::JoinHandle<()> {
        let interval_duration = self.inner.read().config.eviction_check_interval;
        let inner_arc = self.inner.clone();

        tokio::spawn(async move {
            let mut interval = tokio::time::interval(interval_duration);
            loop {
                interval.tick().await;
                let mut inner = inner_arc.write();
                let now = Instant::now();

                // Expired keys
                let expired_keys: Vec<Arc<String>> = inner.entries
                    .iter()
                    .filter(|(_, entry)| now > entry.expires_at)
                    .map(|(k, _)| k.clone())
                    .collect();

                for key in expired_keys {
                    if let Some(entry) = inner.entries.remove(&key) {
                        inner.current_memory -= entry.size;
                        inner.access_order.retain(|k| k != &key);
                        inner.weak_refs.remove(&key);
                        inner.stats.expirations += 1;
                    }
                }

                // Weak ref cleanup (if Arc count is 0)
                let dead_keys: Vec<Arc<String>> = inner.weak_refs
                    .iter()
                    .filter(|(_, weak)| weak.strong_count() == 0)
                    .map(|(k, _)| k.clone())
                    .collect();

                for key in dead_keys {
                    if let Some(entry) = inner.entries.remove(&key) {
                        inner.current_memory -= entry.size;
                        inner.access_order.retain(|k| k != &key);
                        inner.weak_refs.remove(&key);
                        inner.stats.evictions += 1;
                    }
                }
            }
        })
    }
}
```

### 3. src/main.rs (Tests)

```rust
use rust_lru_cache::{LRUCache, CacheConfig};
use std::time::Duration;
use tokio::time::sleep;

#[tokio::main]
async fn main() {
    println!("Running Cache Tests...");

    // 1. Basic Get/Put
    let cache = LRUCache::new(CacheConfig {
        max_entries: 3,
        default_ttl: Duration::from_millis(100),
        ..Default::default()
    });

    cache.put("a".to_string(), "hello".to_string(), None, None);
    assert_eq!(*cache.get("a").unwrap(), "hello");
    assert_eq!(cache.get_stats().size, 1);

    // 2. LRU Eviction
    cache.put("b".to_string(), "world".to_string(), None, None);
    cache.put("c".to_string(), "foo".to_string(), None, None);
    cache.put("d".to_string(), "bar".to_string(), None, None); // Evicts 'a'
    assert!(!cache.has("a"));
    assert!(cache.has("d"));

    // 3. TTL Expiration
    cache.put("x".to_string(), "temp".to_string(), Some(Duration::from_millis(50)), None);
    sleep(Duration::from_millis(80)).await;
    assert!(cache.get("x").is_none());

    // 4. Access Order
    let cache_order = LRUCache::new(CacheConfig {
        max_entries: 3,
        ..Default::default()
    });
    cache_order.put("1".to_string(), "one".to_string(), None, None);
    cache_order.put("2".to_string(), "two".to_string(), None, None);
    cache_order.put("3".to_string(), "three".to_string(), None, None);
    cache_order.get("1"); // Use 1, making 2 the oldest
    cache_order.put("4".to_string(), "four".to_string(), None, None); // Evicts 2
    assert!(!cache_order.has("2"));
    assert!(cache_order.has("1"));

    // 5. Eviction Loop
    let cache_loop = LRUCache::new(CacheConfig {
        max_entries: 10,
        default_ttl: Duration::from_millis(50),
        eviction_check_interval: Duration::from_millis(30),
        ..Default::default()
    });
    cache_loop.put("e1".to_string(), "val1".to_string(), None, None);
    let handle = cache_loop.start_eviction_loop();
    sleep(Duration::from_millis(150)).await;
    assert!(!cache_loop.has("e1"));
    handle.abort();

    println!("All tests passed!");
}
```

### Key Technical Details:
1.  **Memory Management**: Used `Arc<V>` to allow returning references to cached values without cloning the underlying data (satisfying the hot-path requirement).
2.  **Concurrency**: Used `parking_lot::RwLock` for high-performance concurrent access. It is generally faster than the standard library Mutex for read-heavy cache workloads.
3.  **Weak References**: Implemented using `std::sync::Weak`. The background loop checks `strong_count() == 0` to identify objects that are no longer held by any part of the application and removes them from the cache.
4.  **No Unsafe**: The code relies entirely on standard library smart pointers (`Arc`, `Weak`) and safe synchronization primitives.
5.  **Efficiency**: The `access_order` uses `Arc<String>` so that when moving keys to the "front" of the LRU list, we are only moving pointers, not re-allocating strings.
